// Generate 60+ real Tashkent bus routes by cloning and displacing the base routes
const baseRoutes = [...BUS_ROUTES];
const TASHKENT_BUSES = [1, 2, 5, 8, 11, 13, 14, 18, 21, 22, 24, 28, 33, 34, 38, 44, 46, 47, 51, 58, 67, 72, 81, 88, 93, 98, 115, 118, 131, 147, 151, 188, 190, 4, 9, 12, 15, 16, 17, 26, 30, 31, 37, 43, 49, 53, 55, 62, 69, 73, 76, 77, 84, 87, 91, 94, 99, 106, 111, 121, 125, 129];

TASHKENT_BUSES.forEach((num, idx) => {
    if (!BUS_ROUTES.find(r => r.id === `bus_${num}`)) {
        const base = baseRoutes[idx % baseRoutes.length];
        const offsetLat = (Math.random() - 0.5) * 0.08; // 8km displacement
        const offsetLng = (Math.random() - 0.5) * 0.08;
        
        const newPath = base.path.map(p => [p[0] + offsetLng, p[1] + offsetLat]);
        if (Math.random() > 0.5) newPath.reverse(); // Reverse direction for variety
        
        BUS_ROUTES.push({
            id: `bus_${num}`,
            name: `Автобус №${num}`,
            path: newPath
        });
    }
});

// Automatically generate 12 stops for each route and merge them into the global map data
BUS_ROUTES.forEach((route, idx) => {
    for (let i = 0; i < 12; i++) {
        const pathIdx = Math.floor((i / 11) * (route.path.length - 1));
        const coord = route.path[pathIdx];
        MOCK_DATA.bus_stops.push({
            id: `bs_gen_${idx}_${i}`,
            lat: coord[1],
            lng: coord[0],
            name: i === 0 ? `Начальная (Авт. ${route.id.replace('bus_','')})` : i === 11 ? `Конечная (Авт. ${route.id.replace('bus_','')})` : `Остановка (Авт. ${route.id.replace('bus_','')})`,
            extra: `Маршруты: ${route.id.replace('bus_','')}`
        });
    }
});

// Automatically generate ~350 public schools for Tashkent
const tCenterLat = 41.3123;
const tCenterLng = 69.2492;
for (let i = 1; i <= 350; i++) {
    // Exclude the ones already manually hardcoded if their numbers match (110, 50, etc.), but it's fine if they duplicate slightly
    if (i === 110 || i === 50) continue; 
    
    // Distribute them across Tashkent (approx 15x15 km area)
    // Using a normal-like distribution so more schools are near the center, but still spread out
    const radius = Math.pow(Math.random(), 0.5) * 0.1; // up to ~10km
    const angle = Math.random() * Math.PI * 2;
    const latOffset = Math.sin(angle) * radius;
    const lngOffset = Math.cos(angle) * radius * 1.3; // longitude scaling
    
    const types = ['Общеобразовательная', 'Общеобразовательная', 'Общеобразовательная', 'Математический уклон', 'Углубленный английский', 'Информатика и IT', 'Спортивный уклон', 'Специализированная'];
    const extraInfo = types[Math.floor(Math.random() * types.length)];
    
    MOCK_DATA.schools.push({
        id: `s_gen_${i}`,
        lat: tCenterLat + latOffset,
        lng: tCenterLng + lngOffset,
        name: `Школа №${i}`,
        extra: extraInfo
    });
}

// Add some well-known Private/International schools
const privateSchools = [
    { name: 'Presidential School', extra: 'Одаренные дети', latOffset: 0.04, lngOffset: -0.02 },
    { name: 'Cambridge International', extra: 'Кембриджская программа', latOffset: -0.03, lngOffset: 0.05 },
    { name: 'British School of Tashkent', extra: 'Британская программа', latOffset: 0.05, lngOffset: 0.06 },
    { name: 'Tashkent International School (TIS)', extra: 'Международный бакалавриат (IB)', latOffset: -0.06, lngOffset: 0.01 },
    { name: 'Artel Technical School', extra: 'Инженерия и робототехника', latOffset: -0.02, lngOffset: -0.05 }
];

privateSchools.forEach((ps, idx) => {
    MOCK_DATA.schools.push({
        id: `ps_gen_${idx}`,
        lat: tCenterLat + ps.latOffset,
        lng: tCenterLng + ps.lngOffset,
        name: ps.name,
        extra: ps.extra
    });
});

